import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";

function Events() {
  const navigate = useNavigate();

  const [hoverTech, setHoverTech] = useState(false);
  const [hoverNonTech, setHoverNonTech] = useState(false);

  const containerStyle = {
    textAlign: "center",
    marginTop: "80px",
    fontFamily: "Arial, sans-serif",
  };

  const pageStyle = {
    minHeight: "100vh",
    background: "linear-gradient(135deg, #667eea, #764ba2)",
    color: "#fff",
  };

  const headingStyle = {
    fontSize: "32px",
    marginBottom: "40px",
    fontWeight: "bold",
  };

  const buttonBase = {
    padding: "15px 30px",
    margin: "15px",
    fontSize: "18px",
    border: "none",
    borderRadius: "10px",
    cursor: "pointer",
    transition: "all 0.3s ease",
    boxShadow: "0 8px 20px rgba(0,0,0,0.2)",
  };

  return (
    <div style={pageStyle}>
      <Navbar />

      <div style={containerStyle}>
        <h2 style={headingStyle}>Select Event Category</h2>

        {/* Technical Button */}
        <button
          style={{
            ...buttonBase,
            background: hoverTech ? "#ff7eb3" : "#ffffff",
            color: hoverTech ? "#fff" : "#333",
            transform: hoverTech ? "scale(1.1)" : "scale(1)",
          }}
          onMouseEnter={() => setHoverTech(true)}
          onMouseLeave={() => setHoverTech(false)}
          onClick={() => navigate("/technical")}
        >
          Technical Events
        </button>

        {/* Non-Technical Button */}
        <button
          style={{
            ...buttonBase,
            background: hoverNonTech ? "#42e695" : "#ffffff",
            color: hoverNonTech ? "#fff" : "#333",
            transform: hoverNonTech ? "scale(1.1)" : "scale(1)",
          }}
          onMouseEnter={() => setHoverNonTech(true)}
          onMouseLeave={() => setHoverNonTech(false)}
          onClick={() => navigate("/non-technical")}
        >
          Non-Technical Events
        </button>
      </div>
    </div>
  );
}

export default Events;
